        if isinstance(features, (str, bytes)):
            raise TypeError("features must be an iterable of rows")
        try:
            rows = [list(row) for row in features]
        except TypeError as exc:
            raise TypeError("features and rows must be iterable") from exc
        if not allow_empty and not rows:
            raise ValueError("training features cannot be empty")
